#!/usr/bin/env python3
"""
Predictive Analytics Engine - Fase 5 Implementation
Analyzes learning experiences and predicts system issues
"""

import logging
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from typing import Any

logger = logging.getLogger(__name__)


@dataclass
class ForecastWarning:
    """Warning generated by predictive analytics"""

    task_type: str
    failure_rate: float
    threshold_exceeded: float
    sample_size: int
    recommendation: str


@dataclass
class SystemForecast:
    """System forecast result"""

    timestamp: datetime
    warnings: list[ForecastWarning] = field(default_factory=list)
    success_rate_by_task: dict[str, float] = field(default_factory=dict)
    total_experiences_analyzed: int = 0
    analysis_period_hours: int = 24

    @property
    def has_warnings(self) -> bool:
        return len(self.warnings) > 0

    @property
    def details(self) -> dict[str, Any]:  # TODO(TYPE): replace Any with concrete type
        return {
            "warnings": [
                {
                    "task_type": w.task_type,
                    "failure_rate": w.failure_rate,
                    "threshold_exceeded": w.threshold_exceeded,
                    "sample_size": w.sample_size,
                }
                for w in self.warnings
            ],
            "success_rates": self.success_rate_by_task,
            "total_analyzed": self.total_experiences_analyzed,
        }


class PredictiveAnalyticsEngine:
    """
    Engine for analyzing learning experiences and predicting system failures
    Based on failure rate analysis of task types over time periods
    """

    def __init__(
        self,
        failure_threshold: float = 0.20,
        min_sample_size: int = 5,
        analysis_period_hours: int = 24,
    ) -> None:
        self.failure_threshold = failure_threshold
        self.min_sample_size = min_sample_size
        self.analysis_period_hours = analysis_period_hours

        # In-memory storage for learning experiences (would be database in production)
        self._learning_experiences: list[dict[str, Any]] = []  # TODO(TYPE): replace Any with concrete type

        logger.info(f"PredictiveAnalyticsEngine initialized with threshold={failure_threshold}")

    async def add_learning_experience(self, experience: dict[str, Any]) -> bool:  # TODO(TYPE): replace Any with concrete type
        """Add a learning experience to the analytics engine"""
        try:
            # Validate required fields
            required_fields = ["id", "agent_id", "task_type", "success", "timestamp"]
            if not all(field in experience for field in required_fields):
                logger.error(f"Learning experience missing required fields: {required_fields}")
                return False

            # Ensure timestamp is datetime object
            if isinstance(experience["timestamp"], str):
                experience["timestamp"] = datetime.fromisoformat(experience["timestamp"])

            self._learning_experiences.append(experience)
            logger.debug(
                f"Added learning experience {experience['id']} for task {experience['task_type']}"
            )
            return True

        except Exception as e:
            logger.error(f"Failed to add learning experience: {e}")
            return False

    async def generate_system_forecast(self) -> SystemForecast:
        """
        Generate system forecast based on learning experiences from last 24 hours
        Analyzes failure rates by task type and generates warnings
        """
        try:
            current_time = datetime.now(timezone.utc)
            cutoff_time = current_time - timedelta(hours=self.analysis_period_hours)

            # Filter experiences to analysis period
            recent_experiences = [
                exp for exp in self._learning_experiences if exp["timestamp"] > cutoff_time
            ]

            if not recent_experiences:
                logger.info("No recent learning experiences for forecast")
                return SystemForecast(
                    timestamp=current_time,
                    analysis_period_hours=self.analysis_period_hours,
                )

            # Group experiences by task_type
            experiences_by_task = defaultdict(list)
            for exp in recent_experiences:
                experiences_by_task[exp["task_type"]].append(exp)

            # Calculate failure rates and generate warnings
            warnings: list[Any] = []  # TODO(TYPE): replace Any with concrete type
            success_rates: dict[str, Any] = {}  # TODO(TYPE): replace Any with concrete type
            for task_type, task_experiences in experiences_by_task.items():
                if len(task_experiences) < self.min_sample_size:
                    logger.debug(
                        f"Insufficient sample size for {task_type}: {len(task_experiences)} < {self.min_sample_size}"
                    )
                    continue

                # Calculate failure rate
                total_count = len(task_experiences)
                failure_count = sum(1 for exp in task_experiences if not exp["success"])
                failure_rate = failure_count / total_count
                success_rate = 1.0 - failure_rate

                success_rates[task_type] = success_rate

                logger.debug(
                    f"Task {task_type}: {failure_count}/{total_count} failures = {failure_rate:.2%}"
                )

                # Check if failure rate exceeds threshold
                if failure_rate > self.failure_threshold:
                    threshold_exceeded = failure_rate - self.failure_threshold
                    recommendation = self._generate_recommendation(task_type, failure_rate)

                    warning = ForecastWarning(
                        task_type=task_type,
                        failure_rate=failure_rate,
                        threshold_exceeded=threshold_exceeded,
                        sample_size=total_count,
                        recommendation=recommendation,
                    )
                    warnings.append(warning)

                    logger.warning(
                        f"Forecast warning: {task_type} failure rate {failure_rate:.2%} exceeds threshold {self.failure_threshold:.2%}"
                    )

            forecast = SystemForecast(
                timestamp=current_time,
                warnings=warnings,
                success_rate_by_task=success_rates,
                total_experiences_analyzed=len(recent_experiences),
                analysis_period_hours=self.analysis_period_hours,
            )

            logger.info(
                f"Generated forecast with {len(warnings)} warnings from {len(recent_experiences)} experiences"
            )
            return forecast

        except Exception as e:
            logger.error(f"Failed to generate system forecast: {e}")
            return SystemForecast(
                timestamp=datetime.now(timezone.utc),
                analysis_period_hours=self.analysis_period_hours,
            )

    def _generate_recommendation(self, task_type: str, failure_rate: float) -> str:
        """Generate recommendation based on task type and failure rate"""
        if failure_rate > 0.5:
            return f"Critical: Immediate investigation required for {task_type} - failure rate {failure_rate:.2%}"
        elif failure_rate > 0.3:
            return f"High priority: Review and optimize {task_type} implementation"
        else:
            return f"Monitor {task_type} performance and investigate recent failures"

    async def get_performance_metrics(self) -> dict[str, Any]:  # TODO(TYPE): replace Any with concrete type
        """Get performance metrics for the analytics engine"""
        current_time = datetime.now(timezone.utc)
        cutoff_time = current_time - timedelta(hours=self.analysis_period_hours)

        recent_experiences = [
            exp for exp in self._learning_experiences if exp["timestamp"] > cutoff_time
        ]

        total_experiences = len(self._learning_experiences)
        recent_count = len(recent_experiences)

        # Calculate overall success rate
        if recent_experiences:
            overall_success_rate = (
                sum(1 for exp in recent_experiences if exp["success"]) / recent_count
            )
        else:
            overall_success_rate = 0.0

        # Count unique task types
        unique_task_types = len({exp["task_type"] for exp in recent_experiences})

        # Count unique agents
        unique_agents = len({exp["agent_id"] for exp in recent_experiences})

        return {
            "total_experiences": total_experiences,
            "recent_experiences": recent_count,
            "analysis_period_hours": self.analysis_period_hours,
            "overall_success_rate": overall_success_rate,
            "unique_task_types": unique_task_types,
            "unique_agents": unique_agents,
            "failure_threshold": self.failure_threshold,
            "min_sample_size": self.min_sample_size,
            "last_analysis": current_time.isoformat(),
        }

    async def clear_old_experiences(self, max_age_days: int = 7) -> int:
        """Clear learning experiences older than specified days"""
        cutoff_time = datetime.now(timezone.utc) - timedelta(days=max_age_days)

        initial_count = len(self._learning_experiences)
        self._learning_experiences = [
            exp for exp in self._learning_experiences if exp["timestamp"] > cutoff_time
        ]

        removed_count = initial_count - len(self._learning_experiences)

        if removed_count > 0:
            logger.info(
                f"Cleared {removed_count} old learning experiences (older than {max_age_days} days)"
            )

        return removed_count
